"use client"

import * as React from "react"

import { AppShell } from "@/components/shell/app-shell"
import { MockupShell } from "@/components/shell/mockup-shell"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Separator } from "@/components/ui/separator"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  BATCH_NAME,
  QUEUED_CALLS,
  SCENARIO_NAME,
  SCENARIO_RETRY,
  SCHEDULED_CALLS,
  type RetryConfig,
} from "@/lib/mockups/call-retry-data"
import { BatchRetry } from "@/components/mockups/call-retry/batch-retry"
import { ScenarioRetry } from "@/components/mockups/call-retry/scenario-retry"

type Surface = "batch" | "scenario"
type ScenarioState = "off" | "on" | "window"
type Queue = "none" | "queued"

const SCENARIO_STATES: { id: ScenarioState; label: string }[] = [
  { id: "on", label: "Retry on" },
  { id: "off", label: "Retry off" },
  { id: "window", label: "Window invalid" },
]

function seed(state: ScenarioState): RetryConfig {
  if (state === "off") return { ...SCENARIO_RETRY, enabled: false }
  if (state === "window") {
    return { ...SCENARIO_RETRY, windowEnd: { ...SCENARIO_RETRY.windowStart } }
  }
  return SCENARIO_RETRY
}

export default function CallRetryPage() {
  const [surface, setSurface] = React.useState<Surface>("scenario")
  const [state, setState] = React.useState<ScenarioState>("on")
  const [queue, setQueue] = React.useState<Queue>("queued")
  const [overridden, setOverridden] = React.useState(false)
  const [config, setConfig] = React.useState<RetryConfig>(SCENARIO_RETRY)

  const onScenario = surface === "scenario"

  return (
    <MockupShell
      actions={
        <>
          <ToggleGroup
            onValueChange={(next) => {
              if (next) setSurface(next as Surface)
            }}
            size="sm"
            type="single"
            value={surface}
            variant="outline"
          >
            <ToggleGroupItem value="scenario">Scenario</ToggleGroupItem>
            <ToggleGroupItem value="batch">Batch call</ToggleGroupItem>
          </ToggleGroup>

          <Separator className="h-5" orientation="vertical" />

          {onScenario ? (
            <>
              <Select
                onValueChange={(next) => {
                  const chosen = next as ScenarioState
                  setState(chosen)
                  setConfig(seed(chosen))
                }}
                value={state}
              >
                <SelectTrigger aria-label="Scenario state" size="sm">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent position="popper">
                  {SCENARIO_STATES.map((option) => (
                    <SelectItem key={option.id} value={option.id}>
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              <ToggleGroup
                onValueChange={(next) => {
                  if (next) setQueue(next as Queue)
                }}
                size="sm"
                type="single"
                value={queue}
                variant="outline"
              >
                <ToggleGroupItem value="queued">Queued calls</ToggleGroupItem>
                <ToggleGroupItem value="none">Nothing queued</ToggleGroupItem>
              </ToggleGroup>
            </>
          ) : (
            <ToggleGroup
              onValueChange={(next) => {
                if (next) setOverridden(next === "override")
              }}
              size="sm"
              type="single"
              value={overridden ? "override" : "inherit"}
              variant="outline"
            >
              <ToggleGroupItem value="inherit">Inheriting</ToggleGroupItem>
              <ToggleGroupItem value="override">Overridden</ToggleGroupItem>
            </ToggleGroup>
          )}
        </>
      }
      eyebrow={onScenario ? "Build · Scenarios" : "Build · Batch Calls"}
      title="Design retry mechanism across the platform"
    >
      <AppShell
        active={onScenario ? "Scenarios" : "Batch Calls"}
        breadcrumb={
          onScenario
            ? `Scenarios · ${SCENARIO_NAME}`
            : `Batch Calls · ${BATCH_NAME}`
        }
        onNavigate={(title) => {
          if (title === "Scenarios") setSurface("scenario")
          if (title === "Batch Calls") setSurface("batch")
        }}
      >
        <div className="flex flex-1 flex-col p-3 lg:p-4">
          <div className="mx-auto flex w-full max-w-3xl flex-col gap-6">
            <h1 className="text-2xl font-semibold">
              {onScenario ? SCENARIO_NAME : BATCH_NAME}
            </h1>

            {onScenario ? (
              <ScenarioRetry
                config={config}
                onConfigChange={setConfig}
                queued={queue === "queued" ? QUEUED_CALLS : 0}
                scheduled={queue === "queued" ? SCHEDULED_CALLS : 0}
              />
            ) : (
              // Keyed so switching back to Inheriting drops the batch's draft.
              <BatchRetry
                key={overridden ? "override" : "inherit"}
                onOverriddenChange={setOverridden}
                overridden={overridden}
                scenarioConfig={SCENARIO_RETRY}
              />
            )}
          </div>
        </div>
      </AppShell>
    </MockupShell>
  )
}

"use client"

import * as React from "react"
import { toast } from "sonner"

import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemTitle,
} from "@/components/ui/item"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import { SCENARIO_NAME, type RetryConfig } from "@/lib/mockups/call-retry-data"
import { RetrySettingsCard } from "@/components/mockups/call-retry/retry-settings-card"

export function BatchRetry({
  onOverriddenChange,
  overridden,
  scenarioConfig,
}: {
  onOverriddenChange: (overridden: boolean) => void
  overridden: boolean
  scenarioConfig: RetryConfig
}) {
  const [draft, setDraft] = React.useState<RetryConfig>(scenarioConfig)

  return (
    <RetrySettingsCard
      disabled={!overridden}
      onChange={setDraft}
      onSave={() => {
        toast.success("Retry settings saved")
      }}
      scope={
        <Item variant="muted">
          <ItemContent>
            <ItemTitle>
              <Label htmlFor="batch-override">Override scenario</Label>
            </ItemTitle>
            <ItemDescription>
              {overridden
                ? `This batch has its own retry settings. Changes to ${SCENARIO_NAME} no longer reach it.`
                : `Following the ${SCENARIO_NAME} scenario. Change its retry settings and this batch follows.`}
            </ItemDescription>
          </ItemContent>
          <ItemActions>
            <Switch
              checked={overridden}
              id="batch-override"
              onCheckedChange={(next) => {
                if (next) setDraft({ ...scenarioConfig })
                onOverriddenChange(next)
              }}
            />
          </ItemActions>
        </Item>
      }
      value={overridden ? draft : scenarioConfig}
    />
  )
}

"use client"

import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import {
  Field,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import {
  ATTEMPTS_MAX,
  ATTEMPTS_MIN,
  hasRetryErrors,
  retryConfigErrors,
  TIMEZONES,
  type RetryConfig,
} from "@/lib/mockups/call-retry-data"
import { TimeOfDayInput } from "@/components/mockups/call-retry/time-of-day-field"
import { WaitDurationField } from "@/components/mockups/call-retry/wait-duration-field"

export function RetrySettingsCard({
  description,
  disabled = false,
  onChange,
  onSave,
  scope,
  value,
}: {
  description?: string
  disabled?: boolean
  onChange: (value: RetryConfig) => void
  onSave: () => void
  /** The inheritance control, rendered above the fields. */
  scope?: React.ReactNode
  value: RetryConfig
}) {
  const errors = retryConfigErrors(value)
  const fieldsDisabled = disabled || !value.enabled

  function update(patch: Partial<RetryConfig>) {
    onChange({ ...value, ...patch })
  }

  return (
    <Card>
      {/* The gate lives on the title row, not under it. As a row of its own it
          was a label reading "Retry calls" directly beneath a title reading
          "Call retry" — the same three words twice — and a whole line spent on
          one binary. On the title row the switch needs no label at all: the
          title is its label.

          It sits at the card's end edge, where a card-level control is looked
          for, and it is the only control in the header on either surface — the
          inheritance switch that used to share this row now leads the content
          instead. Two switches on one row put "Override scenario" between them,
          labelling neither.

          A bare switch is only unlabelled where the title says what it turns
          off. It does here. */}
      <CardHeader className="mb-2">
        <div className="flex w-full items-center justify-between gap-3">
          <CardTitle>Call retry</CardTitle>
          <Switch
            aria-label="Retry calls"
            checked={value.enabled}
            disabled={disabled}
            id="retry-enabled"
            onCheckedChange={(checked) => {
              update({ enabled: checked })
            }}
          />
        </div>
        {description ? <CardDescription>{description}</CardDescription> : null}
      </CardHeader>

      {/* Retry off greys the fields rather than removing them, so the reader
          can still see what the policy was before it was switched off — and so
          the card does not change height under the hand that flipped it.

          Same read-only language as an inheriting source: every control stays,
          every control is dead. Two ways to say "you cannot edit this" would be
          two things to learn. `retryConfigErrors` already returns nothing while
          disabled, so no greyed field carries a red message and Save stays
          reachable — switching retry off is itself a change worth saving. */}
      <CardContent>
        {scope ? <div className="mb-6">{scope}</div> : null}

        {/* One rhythm, no headings. Banding the six fields 32px apart in pairs
            and 16px within a pair gave the column two spacings to read, and the
            pairs it drew — schedule, then limits — were not a difference any
            reader was asking about. One 24px step between every field, and the
            same step under the header, makes the card a single list. Six
            legends over six fields would be a heading each, which is the thing
            this repo deletes. */}
        <FieldGroup className="gap-6">
          <Field data-disabled={fieldsDisabled || undefined}>
            <FieldLabel htmlFor="retry-attempts">Retry attempts</FieldLabel>
            <Input
              className="max-w-32"
              disabled={fieldsDisabled}
              id="retry-attempts"
              max={ATTEMPTS_MAX}
              min={ATTEMPTS_MIN}
              onChange={(event) => {
                const next = Number(event.target.value)
                if (Number.isNaN(next)) return
                update({
                  attempts: Math.min(
                    Math.max(next, ATTEMPTS_MIN),
                    ATTEMPTS_MAX,
                  ),
                })
              }}
              type="number"
              value={value.attempts}
            />
          </Field>

          <WaitDurationField
            description="Measured from the end of the previous call."
            disabled={fieldsDisabled}
            error={errors.wait}
            id="retry-wait"
            label="Wait between retries"
            onChange={(wait) => {
              update({ wait })
            }}
            value={value.wait}
          />

          {/* The window is one value, so its two ends sit on one line with
                the word that joins them — "9:00 AM to 8:00 PM" — rather than
                as two separately-labelled fields the reader has to pair up.

                A FieldSet with a legend would have been the semantic wrapper
                for the window and its timezone, but `FieldLegend` carries no
                disabled hook, so on an inheriting source it stayed black
                while every other label greyed. One field per row, no
                exceptions — the timezone reads as the window's anyway, sitting
                directly under it. */}
          <Field
            data-disabled={fieldsDisabled || undefined}
            data-invalid={errors.window !== null || undefined}
          >
            <FieldLabel htmlFor="retry-window-start-hour">
              Retry window
            </FieldLabel>
            <div className="flex flex-wrap items-center gap-3">
              <TimeOfDayInput
                disabled={fieldsDisabled}
                id="retry-window-start"
                invalid={errors.window !== null}
                label="From"
                onChange={(windowStart) => {
                  update({ windowStart })
                }}
                value={value.windowStart}
              />

              <span className="text-sm text-muted-foreground">to</span>

              <TimeOfDayInput
                disabled={fieldsDisabled}
                id="retry-window-end"
                invalid={errors.window !== null}
                label="To"
                onChange={(windowEnd) => {
                  update({ windowEnd })
                }}
                value={value.windowEnd}
              />

              <span className="text-sm text-muted-foreground">in</span>

              <Select
                disabled={fieldsDisabled}
                onValueChange={(timezone) => {
                  update({ timezone })
                }}
                value={value.timezone}
              >
                <SelectTrigger
                  aria-label="Timezone"
                  className="max-w-48"
                  id="retry-timezone"
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent position="popper">
                  {TIMEZONES.map((zone) => (
                    <SelectItem key={zone} value={zone}>
                      {zone}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <FieldError>{errors.window}</FieldError>
          </Field>
        </FieldGroup>
      </CardContent>

      <CardFooter className="justify-end border-t">
        <Button disabled={disabled || hasRetryErrors(errors)} onClick={onSave}>
          Save retry settings
        </Button>
      </CardFooter>
    </Card>
  )
}

"use client"

import * as React from "react"
import { toast } from "sonner"

import type { RetryConfig } from "@/lib/mockups/call-retry-data"
import { RetrySettingsCard } from "@/components/mockups/call-retry/retry-settings-card"
import { SaveConfirmDialog } from "@/components/mockups/call-retry/save-confirm-dialog"

export function ScenarioRetry({
  config,
  onConfigChange,
  queued,
  scheduled,
}: {
  config: RetryConfig
  onConfigChange: (config: RetryConfig) => void
  queued: number
  scheduled: number
}) {
  const [confirming, setConfirming] = React.useState(false)

  return (
    <>
      <RetrySettingsCard
        description="Every trigger source uses these settings unless it overrides them."
        onChange={onConfigChange}
        onSave={() => {
          if (queued + scheduled === 0) {
            toast.success("Retry settings saved")
            return
          }
          setConfirming(true)
        }}
        value={config}
      />

      <SaveConfirmDialog
        onConfirm={() => {
          toast.success("Retry settings saved")
        }}
        onOpenChange={setConfirming}
        open={confirming}
        queued={queued}
        scheduled={scheduled}
      />
    </>
  )
}

"use client"

import * as React from "react"

import { InputGroup, InputGroupInput } from "@/components/ui/input-group"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import type { TimeOfDay } from "@/lib/mockups/call-retry-data"

/** Not `<input type="time">`: it only shows AM/PM under an en-US locale. */
export function TimeOfDayInput({
  disabled = false,
  id,
  invalid = false,
  label,
  onChange,
  value,
}: {
  disabled?: boolean
  /** Prefix for the two input ids. */
  id: string
  invalid?: boolean
  /** Accessible name for this end of the window; not rendered. */
  label: string
  onChange: (value: TimeOfDay) => void
  value: TimeOfDay
}) {
  /** Raw text while typing, so `2` is not re-padded to `02` under the caret. Cleared on blur. */
  const [draft, setDraft] = React.useState<null | {
    hour: string
    minute: string
  }>(null)

  const text = draft ?? {
    hour: value.hour.toString().padStart(2, "0"),
    minute: value.minute.toString().padStart(2, "0"),
  }

  function edit(part: "hour" | "minute", raw: string) {
    setDraft({ ...text, [part]: raw })

    const parsed = Number(raw)
    if (raw === "" || Number.isNaN(parsed)) return

    onChange({
      ...value,
      [part]:
        part === "hour"
          ? Math.min(Math.max(parsed, 1), 12)
          : Math.min(Math.max(parsed, 0), 59),
    })
  }

  return (
    <div className="flex items-center gap-2">
      <div className="flex items-center gap-1">
        <InputGroup className="max-w-16">
          <InputGroupInput
            className="text-center"
            aria-invalid={invalid || undefined}
            aria-label={`${label} hour`}
            disabled={disabled}
            id={`${id}-hour`}
            max={12}
            min={1}
            onBlur={() => {
              setDraft(null)
            }}
            onChange={(event) => {
              edit("hour", event.target.value)
            }}
            type="number"
            value={text.hour}
          />
        </InputGroup>

        <span className="text-sm text-muted-foreground">:</span>

        <InputGroup className="max-w-16">
          <InputGroupInput
            className="text-center"
            aria-invalid={invalid || undefined}
            aria-label={`${label} minute`}
            disabled={disabled}
            max={59}
            min={0}
            onBlur={() => {
              setDraft(null)
            }}
            onChange={(event) => {
              edit("minute", event.target.value)
            }}
            type="number"
            value={text.minute}
          />
        </InputGroup>
      </div>

      <ToggleGroup
        disabled={disabled}
        onValueChange={(next) => {
          if (!next) return
          onChange({ ...value, meridiem: next as TimeOfDay["meridiem"] })
        }}
        type="single"
        value={value.meridiem}
        variant="outline"
      >
        <ToggleGroupItem aria-label={`${label} AM`} value="am">
          AM
        </ToggleGroupItem>
        <ToggleGroupItem aria-label={`${label} PM`} value="pm">
          PM
        </ToggleGroupItem>
      </ToggleGroup>
    </div>
  )
}

"use client"

import * as React from "react"

import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group"
import { WAIT_DAYS_MAX, type WaitDuration } from "@/lib/mockups/call-retry-data"

export function WaitDurationField({
  description,
  disabled = false,
  error,
  id,
  label,
  onChange,
  value,
}: {
  description: string
  disabled?: boolean
  error: null | string
  /** Prefix for the three input ids. */
  id: string
  label: string
  onChange: (value: WaitDuration) => void
  value: WaitDuration
}) {
  /** Raw text while typing, as in TimeOfDayField. Cleared on blur. */
  const [draft, setDraft] = React.useState<null | {
    days: string
    hours: string
    minutes: string
  }>(null)

  const text = draft ?? {
    days: value.days.toString(),
    hours: value.hours.toString().padStart(2, "0"),
    minutes: value.minutes.toString().padStart(2, "0"),
  }

  const CEILINGS = { days: WAIT_DAYS_MAX, hours: 23, minutes: 59 }

  function edit(part: "days" | "hours" | "minutes", raw: string) {
    setDraft({ ...text, [part]: raw })

    const parsed = Number(raw)
    if (raw === "" || Number.isNaN(parsed)) return

    onChange({
      ...value,
      [part]: Math.min(Math.max(parsed, 0), CEILINGS[part]),
    })
  }

  return (
    <Field
      data-disabled={disabled || undefined}
      data-invalid={error !== null || undefined}
    >
      <FieldLabel htmlFor={`${id}-days`}>{label}</FieldLabel>
      <FieldDescription>{description}</FieldDescription>

      <div className="flex items-center gap-2">
        <InputGroup className="max-w-32">
          <InputGroupInput
            aria-invalid={error !== null || undefined}
            disabled={disabled}
            id={`${id}-days`}
            max={WAIT_DAYS_MAX}
            min={0}
            onBlur={() => {
              setDraft(null)
            }}
            onChange={(event) => {
              edit("days", event.target.value)
            }}
            type="number"
            value={text.days}
          />
          <InputGroupAddon align="inline-end">
            <InputGroupText>days</InputGroupText>
          </InputGroupAddon>
        </InputGroup>

        <div className="flex items-center gap-1">
          <InputGroup className="max-w-16">
            <InputGroupInput
              className="text-center"
              aria-invalid={error !== null || undefined}
              aria-label="Hours"
              disabled={disabled}
              max={23}
              min={0}
              onBlur={() => {
                setDraft(null)
              }}
              onChange={(event) => {
                edit("hours", event.target.value)
              }}
              type="number"
              value={text.hours}
            />
          </InputGroup>

          <span className="text-sm text-muted-foreground">:</span>

          <InputGroup className="max-w-16">
            <InputGroupInput
              className="text-center"
              aria-invalid={error !== null || undefined}
              aria-label="Minutes"
              disabled={disabled}
              max={59}
              min={0}
              onBlur={() => {
                setDraft(null)
              }}
              onChange={(event) => {
                edit("minutes", event.target.value)
              }}
              type="number"
              value={text.minutes}
            />
          </InputGroup>
        </div>
      </div>

      <FieldError>{error}</FieldError>
    </Field>
  )
}

"use client"

import { HugeiconsIcon, type IconSvgElement } from "@hugeicons/react"

/** No size of its own, so primitives size it through their `[&_svg]:size-4` rules. */
export function icon(glyph: IconSvgElement, displayName: string) {
  const Icon = (
    props: Omit<React.ComponentProps<typeof HugeiconsIcon>, "icon">,
  ) => <HugeiconsIcon icon={glyph} strokeWidth={1.8} {...props} />
  Icon.displayName = displayName
  return Icon
}

