export type TimeOfDay = { hour: number; meridiem: "am" | "pm"; minute: number }

export type WaitDuration = { days: number; hours: number; minutes: number }

export type RetryConfig = {
  attempts: number
  enabled: boolean
  timezone: string
  wait: WaitDuration
  windowEnd: TimeOfDay
  windowStart: TimeOfDay
}

